// zh-CN — 简体中文.
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// TOM: **你**, nunca *您*. É a mesma escolha do du, do ты, do tu e do je — e no chinês ela é bem
// visível: 您 é o tratamento respeitoso que banco e órgão público usam, e num app de amigos soa
// distante. O 你 é como se fala com quem se conhece.
//
// VOCABULÁRIO, decidido uma vez: comunidade = 社区, canal = 频道, sala de voz = 语音房间, mensagem =
// 消息, senha = 密码, transmissão = 直播, lixeira = 回收站, tópico = 话题, insígnia = 徽章, selo = 徽记.
//
// A ESCRITA TEM FONTE PRÓPRIA: 'chinesa' → Noto Sans SC (ver FONTE_DA_ESCRITA em idiomas.ts). Sem ela
// o navegador desenharia quadradinhos no lugar dos caracteres, que é o defeito que o Syden evita
// desde que passou a mapear escritas.

