  'Veja se o microfone está captando a sua voz.': '看看麦克风有没有收到你的声音。',
  'Você ainda não tem nenhuma. Elas chegam como presente ou como recompensa — por exemplo, quando uma ideia sua entra no Syden.': '你还一个都没有。它们会作为礼物或奖励到来——比如，你的某个想法进了 Syden 的时候。',
  'Você entrou por um serviço de fora e ainda não tem senha nesta conta. Defina uma aqui: passa a valer como segundo jeito de entrar, e é o que permite desligar aquele serviço depois.': '你是通过外部服务进来的，这个账号还没有密码。在这里设一个：它会成为第二种登录方式，也正是它让你以后能断开那个服务。',
  'Você perde o acesso aos canais desta comunidade. Para voltar, vai precisar de um convite novo.': '你会失去这个社区频道的访问权。想回来的话，需要一个新的邀请。',
  'ZECA': '小明',
  '{email} — ainda não confirmado': '{email} — 还没确认',
  '{email} — confirmado': '{email} — 已确认',
  'Clique para escolher quais aparecem no seu perfil (até {limite}).': '点一下来选哪些显示在你的资料里（最多 {limite} 个）。',
  'Pessoas bloqueadas': '已屏蔽的人',
  'Quem está aqui não vê as suas mensagens nem você as dele, não consegue abrir conversa privada com você e não pode te mandar pedido de amizade.': '在这里的人看不到你的消息，你也看不到他们的；他们不能和你开私聊，也不能给你发好友申请。',
  '{quantos} sons enviados por vocês': '你们上传的 {quantos} 个音效',
  '1 som enviado por vocês': '你们上传的 1 个音效',
  '15 membros na comunidade': '社区有 15 位成员',
  '5 horas somadas de sala de voz': '语音房间累计 5 小时',
  '5 membros, e pelo menos 3 pessoas diferentes já conversaram': '5 位成员，并且至少 3 个不同的人聊过天',
  'Casa cheia': '满座',
  'conversa em 10 dias diferentes': '在 10 个不同的日子里聊过天',
  'Não para nunca': '从不停下',
  'Nenhum pacote ainda. Monte o primeiro com imagens suas, ou publique os emojis que esta comunidade já tem.': '还没有包。用你自己的图片做第一个，或者把这个社区已经有的表情发布出来。',
  'Os marcos abaixo foram escolhidos para não haver como alcançá-los sozinho — todos precisam de mais de uma pessoa, ao longo do tempo.': '下面这些里程碑是特意选的，一个人没法达成——每一个都需要不止一个人，而且需要时间。',
  'Progresso de {marco}': '{marco} 的进度',
  'Quatro caracteres, um ícone e uma cor que aparecem ao lado do nome de quem é daqui.': '四个字符、一个图标和一种颜色，出现在这里每个人的名字旁边。',
  'Só quem administra pode instalar ou tirar.': '只有管理员能安装或移除。',
  'Turma formada': '队伍成形',
  'Um pacote instalado entra para toda a comunidade: os emojis dele passam a valer nas mensagens de todo mundo.': '装上的包属于整个社区：它的表情会在所有人的消息里生效。',
  'Vozes juntas': '声音在一起',
  'Anil': '靛蓝',
  'Apaga a sua conta, as suas mensagens e o seu avatar. Os canais, emojis e sons que você criou continuam no servidor para os outros.': '删除你的账号、你的消息和你的头像。你建的频道、表情和音效会留在服务器上给其他人。',
