  'com movimento': '会动',
  'Corta a voz em batidas, como as pás girando.': '把声音切成一段段，像旋转的桨叶。',
  'Desligado, a transmissão de quem está na sala aparece como convite e só começa a ser baixada quando você clica em Assistir. Isso poupa internet e processador — principalmente em sala cheia.': '关掉以后，房间里有人开直播会显示成一个邀请，你点“观看”才开始下载。这样省流量也省处理器——人多的房间尤其明显。',
  'Durante uma chamada, esse botão toca estes sons para todos na sala. Instale pacotes prontos ou envie os seus; o que é seu favorito fica na frente do painel.': '通话时，那个按钮会把这些音效放给房间里所有人听。装现成的包，或者上传你自己的；你最喜欢的会排在面板前面。',
