  'Vidente': '预言家',
  'À noite, descubra se alguém é lobisomem. Conte de dia, se achar que vale o risco.': '夜里，查验某人是不是狼人。如果觉得值得冒险，就在白天说出来。',
  'Anjo': '天使',
