  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}»（{onde}）已从 Syden 移除，因为 {quem} 声称拥有其权利。如果你当时获得了发布授权，请在这里回复说明：你的回复会被考虑。在弄清楚之前，它会保持移除状态。条款第 4 节说明了具体做法：https://syden.chat/termos.html#direito-autoral',
