  'Abre os mini-games para jogar com a turma.': '打开小游戏，和大家一起玩。',
  'Cada prateleira guarda os canais da comunidade.': '每一层都放着社区的频道。',
  'Onde o coelho do recado espera quem chega.': '传话兔子在这里等候来访的人。',
  'Alta, para sentar no balcão e conversar.': '高高的，坐在吧台边聊天。',
  'Uma máquina de música antiga, com luzes que acendem à noite.': '一台老式点唱机，晚上会亮起彩灯。',
  'Com caixa de som, pronto para o karaokê.': '带着音箱，随时可以唱卡拉OK。',
  'Redonda, para cartas, tabuleiro e conversa.': '圆桌，适合打牌、玩桌游和聊天。',
  'De madeira, com o assento estofado.': '木头做的，座面有软垫。',
  'Suco, refrigerante e água sempre gelados.': '果汁、汽水和水，永远冰凉。',
  'A cozinha da turma. O botão direito acende e apaga o fogão.': '大家的厨房。右键点击可以开关炉灶。',
  'Um pufe enorme, para afundar e ficar.': '一个超大的懒人沙发，陷进去就不想起来。',
  'Pendurado no gancho, esperando a próxima call.': '挂在钩子上，等待下一次通话。',
  'Fotos dos amigos presas num varal.': '朋友们的照片夹在绳子上。',
  'Recados e ideias presos com alfinete.': '用图钉钉着的留言和点子。',
  'Livros, uma plantinha e um vaso.': '书、一盆小植物和一个花瓶。',
  'Um pôr do sol sobre os campos.': '田野上的日落。',
  'Xícaras, potes e garrafas de suco.': '杯子、罐子和果汁瓶。',
  'Potes de biscoito e pipoca para dividir.': '饼干和爆米花罐，大家分着吃。',
  'As taças das vitórias da turma.': '大家赢来的奖杯。',
  'Um coelho de neon que brilha no escuro.': '在黑暗中发光的霓虹兔子。',
  'Um relógio de madeira para ninguém perder a hora.': '一座木钟，让谁都不会错过时间。',
  'Para quem quiser puxar uma música.': '给想起个头唱歌的人。',
  'Dá no banheiro. Bata antes de entrar.': '通往洗手间。进去前先敲门。',
  'O cartaz do karaokê, em três versões: palco, neon e fogo.': '卡拉OK海报，有三个版本：舞台、霓虹和火焰。',
  'Dois coelhos, um café e a fofoca do dia.': '两只兔子，一杯咖啡，加上今天的八卦。',
  'Café quentinho, ainda soltando fumaça.': '热乎乎的咖啡，还冒着热气。',
  'Suco de laranja com canudinho.': '插着吸管的橙汁。',
  'Uma lata gelada.': '一罐冰汽水。',
  'Uma suculenta pequena, que quase não pede água.': '一盆小多肉，几乎不用浇水。',
  'Uma pilha de livros para ler depois.': '一摞书，留着以后读。',
  'O console da turma, com o controle ao lado.': '大家的游戏机，手柄就在旁边。',
  'Um balde de pipoca para ver a transmissão.': '一桶爆米花，边吃边看直播。',
