  'Monstros de fantasia': '奇幻怪物',
  'Sai um monstro secreto, e cada um chuta outros da lista. Cada chute mostra o que bate com o secreto: tipo, tamanho, nível, alinhamento e como ele se desloca. Quem acertar com menos chutes ganha mais pontos.': '系统随机选出一只秘密怪物，每个人从列表中猜其他怪物。每次猜测都会显示与秘密怪物相符的地方：类型、体型、等级、阵营和移动方式。用越少次数猜中的人得分越多。',
  'Sai uma figura secreta da mitologia, e cada um chuta outras. Cada chute mostra o que bate com a secreta: a mitologia, o tipo, a forma e o que ela governa. Quem acertar com menos chutes ganha mais pontos.': '系统随机选出一位神话中的秘密人物，每个人猜其他人物。每次猜测都会显示与秘密人物相符的地方：所属神话、类型、形态和掌管的领域。用越少次数猜中的人得分越多。',
