  'A subida está andando.': '这次攀登正在进行。',
  'A subida não está andando.': '这次攀登没有在进行。',
  'A tábua racha quando alguém para em cima. Continue andando e empurre os outros para a água!': '有人站上去，木板就会裂开。不停地走，把别人推进水里！',
  'A torre do celeiro': '谷仓高塔',
  'A toupeira-rei caiu!': '鼹鼠王倒下了！',
  'A turma caiu.': '大家都倒下了。',
  'A turma inteira contra a toupeira-rei, que sai das tocas em três fases. Fuja das marcas no chão, pegue os torrões azulados e atire de volta. Ganha a turma, ou ninguém.': '全队一起对抗鼹鼠王，它会分三个阶段从洞里钻出来。躲开地上的标记，捡起蓝色的土块扔回去。要么全队赢，要么没人赢。',
  'Abóboras ladeira abaixo': '南瓜滚下坡',
  'Acerte os corvos que passarem. No coelhinho, não!': '射中飞过的乌鸦。别打小兔子！',
  'Acertos: {n}': '命中：{n}',
  'Afofa a terra': '松土',
  'Água e sol': '水和阳光',
  'Alterne ← e → no ritmo. Com pressa demais, o fôlego acaba.': '有节奏地交替按 ← 和 →。太急的话会喘不过气。',
  'Ao calendário': '去日历',
  'Ao guarda-roupa': '去衣橱',
  'Aperte a seta que aparecer para puxar a corda. Errar trava!': '按出现的方向键来拉绳子。按错会卡住！',
  'Aperte para a roda frear. Ela sempre desliza um pouco antes de parar.': '按下让转盘刹车。它停下之前总会再滑一点。',
  'Aperte sem parar para nadar. Quando vier um tronco, mergulhe!': '不停地按来游泳。木头漂来时，潜下去！',
  'Armadura': '盔甲',
  'Arremesso do nabo': '甩萝卜',
  'Arrumar como quiser': '随心摆放',
  'Arrume a despensa': '整理储藏室',
