  'Balsa a dois': '双人木筏',
  'Barraca de tiro': '射击摊',
  'Bata nas lagartas que saírem das tocas. No coelhinho, não!': '敲打从洞里钻出来的毛毛虫。别敲小兔子！',
  'Bata quando aparecer a flor igual à do quadrinho. Na figura errada, está fora.': '出现和框里一样的花时就敲。敲错图案就出局。',
  'Batata': '土豆',
  'Bate quando der a flor': '见花就敲',
  'Bolinhas': '小球',
  'Bomba de semente': '种子炸弹',
  'Bomba de semente pronta': '种子炸弹已就绪',
  'Bombeie quando o anel acender. Fora do ritmo, o ar escapa.': '圆环亮起时打气。节奏不对，气就会漏掉。',
  'Brasas da fogueira': '篝火火星',
  'Cabo de guerra': '拔河',
  'Cada um rema de um lado: a remada empurra a balsa para o outro. Juntos, ela vai para a frente. Peguem as cenouras!': '每人划一边：划一下，木筏就被推向另一边。一起划，它才会前进。抢胡萝卜吧！',
  'Caiu! Agora é torcer de longe.': '被击落了！现在只能在远处加油了。',
  'Canteiro que encolhe': '缩小的菜畦',
  'Cartas do celeiro': '谷仓翻牌',
  'Celeiro': '谷仓',
  'Cenoura teleguiada': '追踪胡萝卜',
  'Cenouras': '胡萝卜',
  'Chão que desmorona': '崩塌的地面',
  'Chuva de cenouras': '胡萝卜雨',
  'Cinco': '五',
  'Coelhos em teco-tecos sobre a horta, atirando ervilhas e uma cenoura teleguiada de cada vez. Dois acertos dá para aguentar; o terceiro derruba. O último no ar ganha.': '兔子们驾着小飞机飞过菜园，发射豌豆，每次还能发一根追踪胡萝卜。中两下还撑得住，第三下就会坠落。最后留在空中的人获胜。',
  'Colheita em dupla': '双人收获',
  'Coma a torta com a sua dupla, alternando ◀ e ▶. Quem acabar primeiro ganha!': '和搭档一起吃派，交替按 ◀ 和 ▶。先吃完的获胜！',
  'Come as folhas': '吃叶子',
  'Corrida de barquinhos no lago, no riacho e no mangue. A água desliza: tire o pé antes da curva, cuidado com a margem e aproveite a correnteza e as argolas. No Solo, contra o relógio e os fantasmas dos amigos.': '在湖上、小溪和红树林里的划船比赛。水面会打滑：转弯前松开油门，小心岸边，利用水流和圆环。单人模式下，挑战时间和好友的幽灵。',
  'Corrida de cavalinho': '骑马赛跑',
  'Dano da turma: {n}': '全队伤害：{n}',
  'De galho em galho': '枝头跳跃',
  'De que cor é a folha da cenoura?': '胡萝卜的叶子是什么颜色？',
  'Desça pegando as cenouras. Das pedras, fuja!': '一路往下捡胡萝卜。躲开石头！',
  'Descubra quem está escondido. Uma chance só: quanto antes, mais vale.': '找出谁躲在里面。只有一次机会：越早猜中越值钱。',
  'Destampe os potes': '打开罐子',
  'Desvie das brasas. São só três corações!': '躲开火星。只有三颗心！',
  'Dez': '十',
  'Do que uma planta precisa para crescer?': '植物生长需要什么？',
  'Dois acertos você aguenta; o terceiro derruba. Curva fechada perto da cerca protege por um instante.': '中两下还撑得住，第三下就会坠落。在围栏附近急转弯能短暂保护自己。',
  'Duas': '二',
  'Duelo de aviõezinhos': '纸飞机对决',
  'Em dupla: quem está no galho solta os morangos maduros, e quem está embaixo apanha com a cesta.': '两人一组：树枝上的人摇下熟草莓，下面的人用篮子接住。',
  'Em que dia é o aniversário do Syden?': 'Syden 的生日是哪一天？',
  'Empurre os outros para fora do canteiro. A borda que pisca vai cair!': '把别人推出菜畦。闪烁的边缘要塌了！',
  'Encurrale a galinha. Cansada, ela fica lenta.': '把母鸡逼到角落。累了它就会变慢。',
  'Escolha a resposta certa antes que o tempo acabe.': '在时间结束前选出正确答案。',
  'Escolher a torre': '选择高塔',
  'Esconda-se onde a lanterna não vai olhar. Quem tem a lanterna procura!': '躲到灯笼照不到的地方。拿灯笼的人来找！',
  'Esconde-esconde na horta': '菜园捉迷藏',
  'Espanta a chuva': '赶走雨水',
