  'Fase {n} de {total}': '第 {n}/{total} 阶段',
  'Foguete de cenoura': '胡萝卜火箭',
  'Frear': '刹车',
  'Fuga do rio': '逃离河流',
  'Fuja das marcas no chão. Passe por cima de um torrão azulado para pegá-lo e atire de volta na toupeira; a bomba de semente é uma por fase.': '躲开地上的标记。从蓝色土块上经过就能捡起，再扔回鼹鼠身上；种子炸弹每个阶段只有一颗。',
  'Gire cada tampa para o lado da seta, depressa. O lado errado aperta de novo.': '按箭头的方向快速拧开每个盖子。拧反了又会拧紧。',
  'Guarde a ordem da dança. No fim, diga quem dançou na lâmpada marcada.': '记住跳舞的顺序。最后说出谁在标记的灯下跳过舞。',
  'Guarde onde fica cada pote e ponha todos de volta no lugar.': '记住每个罐子的位置，把它们全部放回原处。',
  'Lá de cima rolam abóboras; quem sobe troca de faixa para fugir delas!': '南瓜从上面滚下来；往上爬的人要换道躲开！',
  'Lagarta': '毛毛虫',
  'Lago da horta': '菜园池塘',
  'Leite e mel': '牛奶和蜂蜜',
  'Lesma': '蛞蝓',
  'Leve a nuvem até o canteiro com sede.': '把云带到口渴的菜畦上。',
  'Leve as três tábuas até a ponte. Cuidado com as pedras que afundam!': '把三块木板运到桥边。小心会下沉的石头！',
