  'Na cama': '在床上',
  'Na Corrida dos coelhos, o kart do mascote parece o quê?': '在《兔子赛车》里，吉祥物的卡丁车像什么？',
  'Na sua vez, vire uma carta ou guarde as cenouras. A raposa leva tudo!': '轮到你时，翻一张牌，或者把胡萝卜收好。狐狸会把一切都拿走！',
  'Nenhum amigo subiu esta torre ainda.': '还没有好友爬过这座塔。',
