  'Ouça, repita a batida no mesmo ritmo e acrescente uma no fim.': '听好，用同样的节奏重复鼓点，并在最后加一下。',
  'Paiol': '粮仓',
  'Pare cada faixa com o retrato no lugar, de cima para baixo.': '从上到下，把每一层停在画像对齐的位置。',
  'Pare os três rolos na mesma figura. Cada trinca vale um ponto.': '让三个转轮停在同一个图案上。每凑齐一组得一分。',
