  'Pegue uma cenoura dourada e leve até a porteira. Falta uma: empurre quem estiver carregando!': '拿一根金胡萝卜送到栅栏门。少一根：去推正在搬运的人！',
  'Pilotar (para trás, freia e dá ré)': '驾驶（向后是刹车和倒退）',
