  'Quem ajuda as flores a virar frutos?': '谁帮助花朵结出果实？',
  'Quem está atrás da turma?': '谁躲在人群后面？',
  'Quem está em qual toca?': '谁在哪个洞里？',
  'Quem está no remo manda ondas; quem está na jangada pula na hora!': '拿桨的人掀起波浪；木筏上的人要看准时机跳！',
  'Quem fica atrás do balcão do salão?': '谁站在大厅的吧台后面？',
  'Quiz relâmpago': '快问快答',
  'Rebata quando o rabanete chegar à base. Bem na hora, vai mais longe.': '萝卜飞到本垒时击打。时机越准，飞得越远。',
