  'Regar a horta': '浇灌菜园',
  'Regata da toca': '兔子洞划船赛',
  'Reme alternando ◀ e ▶ quando o remo estiver com você.': '轮到你拿桨时，交替按 ◀ 和 ▶ 划船。',
