  'Sal e areia': '盐和沙子',
  'Segure e solte: cenoura teleguiada': '按住再松开：追踪胡萝卜',
  'Seis': '六',
  'Sem vidas: agora é torcer pela turma.': '没有生命了：现在为队友加油吧。',
  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': '盯住在洞与洞之间移动的动物。最后指出拿气球的那只在哪里。',
  'Silo': '筒仓',
  'Solte o cipó quando ele estiver na faixa clara.': '藤蔓摆到浅色区域时松手。',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': '萝卜朝向场地时松手。转得越快，飞得越远。',
  'Suba até o cata-vento. O que cai e os corvos levam de volta ao último andar.': '爬到风向标那里。被掉落的东西或乌鸦碰到，会回到最后到达的那一层。',
  'Suba o celeiro por tábuas, fardos e vigas que se mexem até o cata-vento lá no alto, desviando das ferramentas que caem e dos corvos. No Solo, contra o relógio e os fantasmas dos amigos.': '踩着会动的木板、草捆和横梁爬上谷仓，到达顶上的风向标，躲开掉落的工具和乌鸦。单人模式下，挑战时间和好友的幽灵。',
  'Subida inválida.': '攀登无效。',
  'Subir contra': '一起比拼',
