  'Balões': '气球',
  'Pegue as caixas e estoure os balões dos outros. Quem fica sem balão sai.': '拿箱子，把别人的气球打爆。气球没了就出局。',
  'Você venceu!': '胜利！',
  '{posicao}º lugar, entre {total}': '第 {posicao} 名，共 {total} 人',
  'Balões que sobraram: {n}': '剩余气球：{n}',
