  'Turbo (da segunda volta em diante)': '加速（从第二圈开始）',
  '{n} voltas': '{n} 圈',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': '能量既是生命也是加速：撞到边缘会消耗，粉色地带会补充。',
  'A nave explodiu: a energia acabou.': '飞船爆炸了：能量耗尽。',
  'Posição: {posicao} de {total}': '名次：{posicao} / {total}',
  'Escolher a pista': '选择赛道',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': '胡萝卜飞船在悬空赛道上竞速，比卡丁车快得多。能量既是生命也是加速：撞到边缘会消耗，粉色地带会补充，冲出赛道就会坠落。单人模式下，挑战时间和好友的幽灵。',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': '卡丁车在封闭的竞技场里，每辆带三个气球。拿箱子，用道具打爆别人的气球：气球没了就出局，坚持到最后的获胜。',
  'Esquadrilha da toca': '兔窝飞行队',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': '胡萝卜小飞机对抗菜园害虫：躲开种子，捡起增援，最后击落机械稻草人。大家飞同样的波次，飞行队的分数会累加。',
  'O espantalho caiu!': '稻草人被击落了！',
  'A praga venceu desta vez.': '这次害虫赢了。',
