  'Minigolfe 3D': '3D 迷你高尔夫',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': '八个 3D 球洞，有坡道、城堡和风车，所有人同时打同一个洞。拖动来瞄准和蓄力，然后松开。总杆数最少的人获胜。',
  'Ver o buraco de cima': '从上方看球洞',
  'Fora da pista! Mais uma tacada.': '出界了！多加一杆。',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': '向侧边拖动瞄准，向下拖动蓄力，然后松开。用键盘：方向键瞄准，按住空格键蓄力。',
  'Futebol dos coelhos': '兔子足球',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': '俯视视角的小场足球。碰到球就能带球，按住空格键射门更有力，按 X 传球。在房间里，队伍会用机器人补齐。',
  'Quantos por time?': '每队几人？',
  'Seu time venceu!': '你的队伍赢了！',
  'Seu time perdeu.': '你的队伍输了。',
