  'Ninguém para jogar.': '没有人可以一起玩。',
  'Caça às pragas da horta': '菜园害虫大狩猎',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': '乌鸦和蚱蜢来袭菜园。趁它们逃走前瞄准点击：弹药有限，每一波都更快。得分最多的人获胜。',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': '趁害虫逃走前瞄准点击。每开一枪用掉一根胡萝卜。',
