  'Tacadas: {n}': '杆数：{n}',
  'Puxe a bola para trás e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': '把球往后拉再松开。用键盘：方向键瞄准，按住空格键蓄力。',
  'Na água! Mais uma tacada.': '掉进水里！多加一杆。',
