  'Para a direita': '向右',
  'Setas para correr, Espaço para pular (segure para ir mais alto).': '方向键奔跑，空格键跳跃（按住可以跳得更高）。',
  'Nenhum amigo jogou esta fase ainda.': '还没有好友玩过这一关。',
  'Chuva na horta: todo mundo ganha {n} cenouras.': '菜园下雨了：每个人得到 {n} 根胡萝卜。',
  '{nome} achou {n} cenouras escondidas.': '{nome} 找到了 {n} 根藏起来的胡萝卜。',
  '{nome} trocou de lugar com {outro}.': '{nome} 和 {outro} 交换了位置。',
  'Faltou gente: a partida acabou antes do fim, sem troféus.': '人数不够：比赛提前结束，没有奖杯。',
  'Saiu antes do fim': '中途离开',
  'Jogar o dado': '掷骰子',
  '{nome} comprou a cenoura dourada!': '{nome} 买下了金胡萝卜！',
  'Comprar a cenoura dourada por {preco} cenouras?': '用 {preco} 根胡萝卜买金胡萝卜吗？',
  'Comprar': '购买',
  '{nome} chegou à cenoura dourada.': '{nome} 到达了金胡萝卜。',
  'Quantas rodadas?': '几轮？',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': '兔子们保卫菜园，对抗狐狸、乌鸦和一只獾。一起前进，打出连击，互相照应：1 到 4 人。',
  'Pulo do coelho': '兔子跳跳',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': '平台竞速：奔跑、跳跃，别掉下去。单人时，与时间和好友的幽灵比拼；和伙伴们一起时，实时比赛，跑一关或三关全跑。',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': '交换两个相邻的蔬菜，凑齐三个或更多相同的。方块堆会不停上升：别让它堆到顶。和伙伴们一起时，连锁和连击会给其他人送去箱子。',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': '六个迷你高尔夫球洞，大家同时打同一个洞。把球往后拉再松开就能击球。总杆数最少的人获胜。',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': '每个人轮到自己时掷骰子，在菜园里前进。收集胡萝卜来买金胡萝卜，每轮结束后伙伴们一起玩一个小游戏。金胡萝卜最多的人获胜。',
  'Os pódios e as conquistas da turma': '领奖台和大家的成就',
