  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': '经典多米诺，2 到 4 人（4 人时两两组队）。在两端接上点数相同的骨牌，最先出完的人拿走其他人手里的点数。',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': '圣保罗式特鲁科，有翻牌和王牌，2 人对战或 4 人两两组队。喊特鲁科，加到六、九、十二，或者认输逃跑。先拿到 12 分的获胜。',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': '巴西跳棋：能吃必须吃，向前向后都可以，王棋可沿整条斜线行走。房间里的人观战。',
