  'Cozinha da toca': '洞穴厨房',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': '从箱子里拿食材，在砧板上切好，在炉灶和烤箱里烹饪别烧焦，装盘后在窗口上菜。大家拿到的订单都一样：3 分钟内上菜最多的人获胜。',
