  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "洞穴地牢",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "一起穿过蘑菇王的洞穴：满是小怪的房间、装着能飞出去再飞回来的胡萝卜的宝箱、需要两人同时踩下的机关，还有上锁的门。1 到 4 人。",
