  "A mesma posição pela terceira vez empata, e 20 lances só de dama sem comer também.": "同一局面第三次出现即和棋；连续 20 步只有王棋走动且没有吃子也是和棋。",
  "À noite, veja quem os lobisomens atacaram. Uma poção salva essa pessoa e outra tira alguém do jogo; cada uma vale uma vez.": "夜里，看看狼人袭击了谁。一瓶药救这个人，另一瓶让某人出局；每瓶只能用一次。",
