  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "王牌是翻牌的下一个点数，能赢所有牌。王牌之间由弱到强：方块、黑桃、红心、梅花，也就是“扎普”。",
