  "Acertos em sequência: {n}": "连续答对：{n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "按骰子前进，买下停留的首府。停在别人城市的人要付租金。",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "每行、每列和每个 3 × 3 宫都有 1 到 9 的数字，不能重复。",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "每人发 3 张牌。3 轮中赢 2 轮的人拿下这一手。",
  "Campeonato": "锦标赛",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "到 11 分时，该队看牌后决定是否打十一分局。先到 12 分的获胜。",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "拥有整个地区后，最多可盖 4 栋楼：每盖一栋租金就涨。",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "有星星时，重拳（★）会一次用掉全部星星，伤害更高。",
  "Dica": "提示",
  "Dica: este problema não pontua": "提示：这道题不计分",
  "Dica: tira 10 segundos": "提示：扣 10 秒",
  "Eliminação": "淘汰赛",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "把点数相同的骨牌接到桌上的一端。",
  "Escolha a casa e depois o número. O lápis anota só para você.": "先选格子，再选数字。铅笔笔记只有你自己看得到。",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "躲开攻击后立刻出拳：这就是反击，能得到一颗星星。",
  "Fora da corrida na volta {n}.": "第 {n} 圈出局。",
  "Força das cartas": "牌的大小",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "回合结束时资产最多的人获胜，或者最后剩下的人。",
  "Iniciante": "入门",
  "Mestre": "大师",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "连续模式中，每答对一题就会出更难的题，答错一次就结束。",
  "O número pequeno no botão diz quantos ainda faltam.": "按钮上的小数字表示还剩几个。",
  "Os cinco traçados seguidos contra o computador, com pontos.": "五条赛道连续与电脑对战，按积分。",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "喊特鲁科，这一手就值 3 分。被喊的一方可以接受、认输，或加到 6、9、12。",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "出完牌的人拿走其他人手里的点数。如果卡死，手里点数最少的人拿走。",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "没有能接的牌就摸牌。没有牌可摸，就跳过这一轮。",
  "Sequência": "连续",
  "Soque quando a luva brilhar: o golpe para e você ganha uma estrela.": "在拳套闪光时出拳：攻击会停下，你还能得到一颗星星。",
  "Treino livre": "自由练习",
