  "Chuva de estrelas": "流星雨",
  "Com a captura, cercar duas pedras do outro entre duas suas tira as duas; cinco capturas também vencem.": "开启提子时，用自己的两颗子夹住对方两颗子，就把两颗都提掉；提子五次也算赢。",
  "Com a restrição 3-3, as escuras não podem fazer dois três abertos de uma vez.": "开启三三禁手时，黑方不能同时做出两个活三。",
  "Com as batidas especiais, bater com carroça ou com a pedra que serve nas duas pontas vale o dobro; a carroça nas duas pontas, o quádruplo.": "开启特殊出完时，用双牌或两头都能接的牌出完算双倍；两头都能接的双牌算四倍。",
