  "No mineiro, a mão vale 2, e o truco, o seis, o nove e o doze valem 4, 8, 10 e 12. Com 10 pontos, é a mão de dez: jogar valendo 4, ou correr e dar 2.": "米纳斯式中，一局算 2 分，叫特鲁科、六、九、十二分别算 4、8、10、12 分。到 10 分时是十分局：按 4 分来打，或者逃跑送 2 分。",
