  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "抽出一个秘密动物，每个人猜别的动物。每猜一次，就显示和秘密动物相同的地方：纲、食性、栖息地和体重。猜的次数越少，得分越高。",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "抽出一个秘密恐龙，每个人猜别的恐龙。每猜一次，就显示和秘密恐龙相同的地方：时期、食性、类群、体长和发现地。猜的次数越少，得分越高。",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "抽出一个秘密化学元素，每个人猜别的元素。每猜一次，就显示和秘密元素相同的地方：类别、物态、周期、族和原子序数。猜的次数越少，得分越高。",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "抽出巴西的一个秘密州，每个人猜别的州。每猜一次，就显示到秘密州的距离和方向、地区、人口、面积、海岸线和是否与外国接壤。猜的次数越少，得分越高。",
